<?php
defined('ABSPATH')||exit;final class SPL_Activator{
 public static function register(){register_post_type(SPL_Helpers::TYPE,array('labels'=>array('name'=>'PDF Library','singular_name'=>'Library Document'),'public'=>true,'show_ui'=>true,'show_in_rest'=>false,'has_archive'=>'library-documents','rewrite'=>array('slug'=>'library-document'),'supports'=>array('title','editor','excerpt','thumbnail','author','comments','revisions'),'taxonomies'=>array(SPL_Helpers::TAX,SPL_Helpers::DOCTYPE)));register_taxonomy(SPL_Helpers::TAX,SPL_Helpers::TYPE,array('public'=>true,'show_ui'=>false,'hierarchical'=>true,'rewrite'=>array('slug'=>'library-category')));register_taxonomy(SPL_Helpers::DOCTYPE,SPL_Helpers::TYPE,array('public'=>true,'show_ui'=>false,'hierarchical'=>true,'rewrite'=>array('slug'=>'document-type')));}
 public static function activate(){self::register();$a=get_role('administrator');if($a)$a->add_cap('manage_pdf_library');foreach(array(SPL_Helpers::TAX=>SPL_Helpers::categories(),SPL_Helpers::DOCTYPE=>SPL_Helpers::types())as$tax=>$items)foreach($items as$slug=>$name)if(!get_term_by('slug',$slug,$tax))wp_insert_term($name,$tax,array('slug'=>$slug));global$wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();dbDelta("CREATE TABLE {$wpdb->prefix}spl_user_data (id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,document_id bigint unsigned NOT NULL,data_type varchar(20) NOT NULL,page_number int unsigned NOT NULL DEFAULT 0,note text NOT NULL,reaction varchar(10) NOT NULL,progress int unsigned NOT NULL DEFAULT 0,updated_at datetime NOT NULL,PRIMARY KEY(id),KEY user_document(user_id,document_id),KEY data_type(data_type)) {$c};");dbDelta("CREATE TABLE {$wpdb->prefix}spl_reports (id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,document_id bigint unsigned NOT NULL,reason varchar(40) NOT NULL,details text NOT NULL,status varchar(20) NOT NULL DEFAULT 'open',created_at datetime NOT NULL,PRIMARY KEY(id),KEY document_id(document_id),KEY status(status)) {$c};");$spf=(array)get_option('spf_page_map',array());$m=array();$m['library']=self::page(!empty($spf['pdf'])?absint($spf['pdf']):0,'PDF Library','pdf-library','[spl_library]');$m['upload']=self::page(0,'Upload Library Document','upload-library-document','[spl_upload]');$m['saved']=self::page(0,'Saved Documents','saved-documents','[spl_saved]');$m['reading']=self::page(0,'Reading Workspace','reading-workspace','[spl_reading_workspace]');update_option('spl_page_map',$m,false);$spf['pdf']=$m['library'];update_option('spf_page_map',$spf,false);SPL_Helpers::storage();set_transient('spl_notice','1',120);flush_rewrite_rules();}
 private static function page($id,$title,$slug,$code){$p=$id?get_post($id):get_page_by_path($slug);if($p instanceof WP_Post){if(get_post_meta($p->ID,'_spf_managed_page',true)||get_post_meta($p->ID,'_spl_managed',true)||false!==strpos($p->post_content,'[sabri_platform_module')){wp_update_post(array('ID'=>$p->ID,'post_content'=>$code));update_post_meta($p->ID,'_spl_managed','1');}return$p->ID;}$id=wp_insert_post(array('post_title'=>$title,'post_name'=>$slug,'post_content'=>$code,'post_status'=>'publish','post_type'=>'page'));update_post_meta($id,'_spl_managed','1');return$id;}public static function deactivate(){flush_rewrite_rules();}
}

